windows.script:
Folder := A_ScriptDir
Current := ""
Dirty := false
PaneOn := true
WrapOn := false

; The text files in the folder, in the list on the left.
ListFolder() {
    global files, Folder, g
    files.Delete()
    names := []
    loop files Folder "\*.*"
        if RegExMatch(A_LoopFileExt, "i)^(ahk|txt|md|js|json|ini|css|html?|py|ps1|sql|xml|log|csv)$")
            names.Push(A_LoopFileName)
    if names.Length
        files.Add(names)
    g.Status("msg", Folder)
}
OpenFile(name) {
    global ed, Folder, Current, Dirty, g
    if (name = "")
        return
    SaveFile(true)
    Current := Folder "\" name
    ed.Load(FileRead(Current, "UTF-8"))
    Dirty := false
    SplitPath(name, , , &ext)
    ext := StrLower(ext)
    langs := Map("ahk", "ahk", "js", "js", "json", "json", "md", "md", "css", "css", "htm", "html",
                 "html", "html", "xml", "xml", "ini", "ini", "ps1", "ps1", "py", "py", "sql", "sql")
    ed.SetLanguage(langs.Has(ext) ? langs[ext] : "plain")
    g.Status("lang", langs.Has(ext) ? StrUpper(ext) : "Plain text")
    g.Status("msg", name)
}
; quiet: saving on the way to another file -- only if it changed, and
; never asking for a name.
SaveFile(quiet := false) {
    global ed, Folder, Current, Dirty, g
    if (quiet && !Dirty)
        return
    if (Current = "") {
        if quiet
            return
        name := g.Prompt("Save it as", "Save", "untitled.txt")
        if (name = "")
            return
        Current := Folder "\" name
    }
    try FileDelete(Current)
    FileAppend(ed.Value, Current, "UTF-8")
    Dirty := false
    if !quiet {
        g.Toast("Saved", 1200, "success")
        ListFolder()
    }
}
NewFile() {
    global ed, Current, Dirty, g
    SaveFile(true)
    Current := "", Dirty := false
    ed.Load("")
    g.Status("msg", "A new file -- Ctrl+S names it")
}
PickFolder() {
    global Folder
    d := DirSelect("*" Folder, 0, "Pick a folder of text files")
    if (d != "") {
        Folder := d
        ListFolder()
    }
}
TogglePane() {
    global PaneOn
    PaneOn := !PaneOn
    MainState(PaneOn ? "panes" : "nopanes")
}
ToggleWrap() {
    global ed, WrapOn
    WrapOn := !WrapOn
    ed.SetOption("wrap", WrapOn ? 1 : 0)
}
